import base64, pathlib

ROOT = pathlib.Path(__file__).resolve().parent
SHOTS = ROOT.parent / "shots"

def img(name, alt):
    data = base64.b64encode((SHOTS / name).read_bytes()).decode()
    return f'<figure><img src="data:image/png;base64,{data}" alt="{alt}" loading="lazy"><figcaption>{alt}</figcaption></figure>'

SEV = {"high": "High", "medium": "Medium", "low": "Low"}

def finding(n, sev, title, saw, why, fix, figs=(), where=""):
    figs_html = "".join(img(f, a) for f, a in figs)
    where_html = f'<p class="where"><span>Where</span>{where}</p>' if where else ""
    return f'''
<article class="finding" id="f{n}">
  <header><span class="num">{n:02d}</span><span class="sev sev-{sev}">{SEV[sev]}</span><h3>{title}</h3></header>
  <div class="body">
    <p class="lead">{saw}</p>
    {figs_html}
    <p><strong>Why it matters.</strong> {why}</p>
    <p><strong>Suggested change.</strong> {fix}</p>
    {where_html}
  </div>
</article>'''

findings = [
finding(1, "high", "The moment after a printer is added is left to the model, and it changed every run",
 "Same input, three runs, three different scripts. Run A: “creality k1” was saved at once and the reply ended with no offer to connect; the offer only appeared later, after I changed the nozzle. Run B: “Prusa MK4S” chosen from a chip was saved at once and nothing was offered at all. Run C (dark theme): the printer was saved and the offer came as bare “Yes / No” chips.",
 "This is the one step every new user goes through, and it is the step that tells them the printer is ready. When the receipt line, the offer, and the chip labels are different each time, the product feels improvised, and a user who never sees the offer never learns that connecting exists.",
 "Make the receipt deterministic. Either the app posts a fixed line and chip row when <code>printer_add</code> succeeds (“Creality K1 is ready. Connect it over Wi-Fi?” · Connect it · Not now), or the prompt names the exact chip text and requires the offer, with a live test that counts it across ten runs the way the nozzle rule was measured. Kenneth's decision that the assistant chooses the chips still holds if the prompt fixes the wording for this one moment.",
 [("02-add-k1-added.png", "Run A: the K1 was saved from the name alone. The reply reads as a receipt, but nothing else marks the change and no next step is offered."),
  ("10-dark-k1-profile-id-leak.png", "Run C: the same input, now with an offer and bare Yes / No chips. The second card is finding 06.")],
 "printerInstructions.ts (the connect rules at lines 52–65) and PrinterConversation::add"),

finding(2, "high", "The connection card can appear before there is anything to connect to",
 "After I tapped “Yes, connect it”, a card titled “Connect to Creality K1” appeared with an API-key field and a Connect button. There was no address yet: the model had passed the printer's name as the address. Pressing Connect ran the attempt, the card flipped to “Sent”, and only then did the assistant ask for the address.",
 "The card is the only irreversible-looking control in the thread, and it is asking the user to commit to an action the app cannot perform. The user pays for the model's mistake with a dead click and a confusing “Sent”.",
 "Validate the address in <code>preflight_tool</code> before the card is drawn: reject a value that equals the printer's name, contains spaces, or is not a host name, IP or URL, and return <code>address_needed</code> so the assistant asks first. The card should also show what it will do in plain words (“Send files to 192.168.1.42 over Moonraker”), not only a title.",
 [("04-connect-card-no-address.png", "The card titled with the printer's name, not an address."),
  ("05-connect-sent-then-asks-address.png", "After Connect: the card reads “Sent”, then the assistant asks for the address it should have had first.")],
 "PrinterConversation.cpp, preflight_tool, host branch (accepts any non-empty address)"),

finding(3, "high", "Thirty seconds of silence, then a dead end",
 "After Connect, nothing on screen changes for the whole attempt (about 30 s): the card says “Sent”, the composer is idle, no spinner, no “Connecting…”. When it fails, the assistant explains, but offers no chips, so the user must type the next move.",
 "A user who does not know the attempt is running will press Connect again, retype the address, or leave. The failure is the most common outcome on a first try (wrong IP, printer asleep, different subnet), so it needs the best-designed path in the flow.",
 "Give the card three states in its own words: “Connecting…” with a progress indicator while the app waits, then “Connected” or “Couldn't reach 192.168.1.42”. Keep the assistant's reply for what to do next and end it with chips: Try again · Enter the details myself · Skip for now. “Sent” should not exist as a label; it describes the message plumbing, not the outcome.",
 [("06-connect-failed.png", "The failed attempt: two “Sent” cards and a reply with no way forward but typing.")],
 "PrinterPanel.tsx line 84 (the “Sent” / “Cancelled” label), ToolActivity state → card copy"),

finding(4, "high", "Home says the printer “Sends files over Wi-Fi” right after the connection failed",
 "Back on Home, the Creality K1 card carries the line “Sends files over Wi-Fi”. The connection test had just failed. The line appears because the address was saved to the printer profile regardless of the test result, and the Home backend reads only whether an address exists.",
 "This is a false claim in the one place the user will look to check the printer's state. The next thing they do is slice and press Print, and it fails again, now far from the conversation that could help.",
 "Either save the host only when the test succeeds, or keep the address and show the outcome: “Couldn't reach 192.168.1.42” with a Retry action, and the quiet “Sends files over Wi-Fi” only once a test has passed.",
 [("12-home-card-after-failed-connect.png", "The K1 card after the failed test."),
  ("13-home-card-menu.png", "The card menu: “Connect…” is the right escape hatch, but the card above it contradicts it.")],
 "OrcaHomeBackend.cpp lines 224–228 (print_host non-empty → “Sends files over Wi-Fi”)"),

finding(5, "medium", "Ambiguous matches show three identical cards and then repeat them as chips",
 "“prusa mk4” returned three cards (MK4, MK4S, MK4S HF) with the same picture and the same build volume, followed by the question and three chips carrying the same names. The cards are not tappable; only the chips are.",
 "The cards take most of the screen and carry no information that helps choose. The chips are the only control, but they look like an afterthought under the cards. Two representations of one list doubles the reading for no gain.",
 "Make the card the control: tapping a card sends its name as the reply, and the chip row disappears for this case. Give each card one line that separates it from its siblings (year, hotend, or the profile's own note) when the catalog has it; when it does not, a single compact list with a picture beats three full cards.",
 [("07-candidates-cards-and-chips.png", "Three cards, then the same three names as chips.")],
 "PrinterPanel.tsx PrinterBlockView (printers block), replyChoices.ts"),

finding(6, "medium", "A raw profile id leaks into the candidate list",
 "In the dark run the same “creality k1” produced a second card, “Creality K1_CFS-C”, with no build volume and a thumbnail of a different shape. That is an internal profile name for a K1 variant.",
 "Underscores, suffix codes, and an empty size line tell the user the app is showing them its database. It also invites the wrong pick.",
 "Filter variant profiles out of <code>printer_identify</code> results when they lack artwork or a build volume, or map them to their display name and fold them under the parent model. A card with an empty size line should never render.",
 [("10-dark-k1-profile-id-leak.png", "The K1_CFS-C card beside the real K1.")],
 "PrinterCatalog.cpp (which profiles become catalog printers), PrinterConversation::identify"),

finding(7, "medium", "The Change conversation opens blind",
 "“Printer settings…” opens with one line: “This is the Creality K1. Tell me what changed on it, or ask anything about it.” No picture, no nozzle, no connection state, no chips. I had to ask “what nozzle is it set up with?” to learn it was 0.6 mm.",
 "The user opened this to check or change something. Making them ask for the current state first is a round trip the app can skip, and the empty screen gives no hint of what kinds of change are possible.",
 "Open with an app-authored summary card (picture, name, nozzle, connection state) and chips for the common changes: Changed the nozzle · Loaded a new spool · Connect it. The assistant's line then only needs to invite anything else.",
 [("08-change-opener.png", "The Change opener.")],
 "printerWords.ts opening(), PrinterSessionPayload.context.printer (already carries nozzle and connected)"),

finding(8, "medium", "Connect-only opener forgets the address that just failed",
 "From the card's “Connect…” entry the assistant asks for the address from scratch, although 192.168.1.42 is saved on the printer and was the address that failed a minute earlier.",
 "The user is asked to repeat themselves, and the assistant cannot say the one useful thing: that this address did not answer last time.",
 "Add the saved host and the last outcome to the session context so the opener can say “192.168.1.42 didn't answer last time. Try it again, or give me a different address?” with chips for both. Conversation memory across openings stays off; this is printer state, not chat history.",
 [("09-connect-opener.png", "The Connect opener.")],
 "PrinterContext.printer (add host address and last connection result)"),

finding(9, "low", "The panel's overflow menu wraps both labels and ignores Escape",
 "The “…” menu is 128 px wide, so “Browse the full printer list” and “Open printer settings” each break onto two lines. Escape does not close it; only a click elsewhere does.",
 "A two-line label in a two-item menu reads as a layout bug, and Escape is the first thing a keyboard user tries.",
 "Let the menu size to its longest label with <code>white-space: nowrap</code> (or raise the min-width token), and close it on Escape and on focus leaving the menu.",
 [("11-overflow-menu.png", "The overflow menu at its current width.")],
 "styles.css .chat-menu (min-width: 128px), ChatNavigation.tsx"),

finding(10, "low", "Chips could not be reached from the keyboard, and show no focus state",
 "With the composer focused, Tab, Tab and Shift+Tab three times never put a visible focus ring on a chip, and Return did nothing. I could not confirm the handoff's promise that chips are reachable with Tab and Enter.",
 "Keyboard reach is the accessibility baseline for a control that is the primary way to answer.",
 "Put the chips in the tab order right before the composer, give <code>.reply-chip:focus-visible</code> a visible ring from the token file, and add a test that tabs from the composer to the last chip.",
 [],
 "styles.css .reply-chip, MessageList.tsx (chip row)"),

finding(11, "low", "The Photo button opens a generic file picker",
 "The picker is titled “Select a file”, opens in a folder of 3D models, and lists .3mf and .stl files, which is what the rest of the app opens. Nothing says it wants a photo.",
 "The tip banner sells the photo as the fastest way; the picker then looks like the wrong dialog.",
 "Title it “Choose a photo”, filter to image types, and start in Pictures or the last photo folder rather than the model folder.",
 [],
 "AgentHost / native attach_file handling for the printer panel"),

finding(12, "low", "Adding a printer marks the project as unsaved",
 "As soon as the K1 was saved, the window title changed from “Untitled” to “*Untitled”. Nothing in the conversation touched a project.",
 "Users learn the asterisk means “you have unsaved work”. Getting it from a printer-setup chat will make them look for what they changed.",
 "Adding or changing a printer should not dirty the project, or the panel should say what it changed if it must.",
 [],
 "PrinterBackend add/change path (preset selection marks the plater dirty)"),
]

